notes = #{notes}, 
total_amount = #{totalAmount},
updated_at = #{updatedAt}
WHERE id = #{id}

mapper.select:
SELECT id, total_amount, payment_status, order_status, created_at
FROM orders 
WHERE tenant_id = #{tenantId} 
AND DATE(CONVERT_TZ(created_at, '+00:00', 'America/Vancouver')) = #{date}
ORDER BY created_at DESC

SELECT id, total_amount, payment_status, order_status, created_at
FROM orders 
WHERE tenant_id = #{tenantId} 
AND DATE(CONVERT_TZ(created_at, '+00:00', 'America/Vancouver')) BETWEEN #{startDate} AND #{endDate}
ORDER BY created_at DESC
